action_details.action_postfix:
apportionment.state_taxable_income get /taxable_income xdef
0.0 /calculated_tax xdef
taxable_income get apportionment.vt_bracket_threshold_1 get le
{
  taxable_income get apportionment.vt_tax_rate_tier1 get mul /calculated_tax xdef
}
{
  taxable_income get apportionment.vt_bracket_threshold_2 get le
  {
    apportionment.vt_bracket_threshold_1 get apportionment.vt_tax_rate_tier1 get mul /calculated_tax xdef
    taxable_income get apportionment.vt_bracket_threshold_1 get sub apportionment.vt_tax_rate_tier2 get mul calculated_tax get add /calculated_tax xdef
  }
  {
    apportionment.vt_bracket_threshold_1 get apportionment.vt_tax_rate_tier1 get mul /calculated_tax xdef
    apportionment.vt_bracket_threshold_2 get apportionment.vt_bracket_threshold_1 get sub apportionment.vt_tax_rate_tier2 get mul calculated_tax get add /calculated_tax xdef
    taxable_income get apportionment.vt_bracket_threshold_2 get sub apportionment.vt_tax_rate_tier3 get mul calculated_tax get add /calculated_tax xdef
  } ifelse
} ifelse
calculated_tax get /apportionment.vt_calculated_tax xdef
calculated_tax get apportionment.state_credits get sub 0.0 max /apportionment.state_tax xdef
apportionment.state_payments get apportionment.state_tax get sub /apportionment.state_refund_or_owed xdef
"VT tax calculated using graduated brackets: 6% on first $10K, 7% on $10K-$25K, 8.5% over $25K (one of highest state rates). Reference: 32 V.S.A. 5832" job.audit_trail swap addto
